        int cpus = Runtime.getRuntime().availableProcessors();
        System.out.println("Disponível para paralelismo: " + cpus);

        // Threads ativas totais
        long ativos = Thread.activeCount();
        System.out.println("Threads ativas (inclui daemon): " + ativos);

        // Threads não-daemon ativas
        long naoDaemonAtivos = ativos - Runtime.getRuntime().activeDaemonCount();
        System.out.println("Threads não-daemon ativas: " + naoDaemonAtivos);

        // Em Java 9+
        try {
            Method m = Thread.class.getMethod("availableThreads");
            int avail = (Integer) m.invoke(null);
            System.out.println("Threads disponíveis (Java 9+): " + avail);
        } catch (NoSuchMethodException e) {
            System.out.println("Método availableThreads não disponível nesta versão.");
        }
    }
}
```

